import AppKit

/// Each provider's logo, in its colour: the provider tabs and Settings. The marks are their owners' trademarks, shown
/// only to name the service an account belongs to. Path data from Simple Icons (CC0) and, for OpenAI, xAI and Z.ai,
/// Lobe Icons (MIT, © LobeHub); see THIRD-PARTY-NOTICES.md. Each is drawn once per size, on first use, by AppKit's
/// own SVG renderer.
@MainActor
enum ProviderLogo {
    /// A mark on a 24-point grid.
    struct Mark {
        enum Rule: String { case evenodd, nonzero }
        let rule: Rule
        let paths: [String]
    }

    private static var cache: [String: NSImage] = [:]

    /// The provider's logo, `size` points square, filled with its brand colour; a dot of that colour for a provider
    /// without one.
    static func image(_ provider: Provider, size: CGFloat) -> NSImage {
        let key = "\(provider.id)/\(size)"
        if let image = cache[key] { return image }
        let color = provider.brandColor
        let image: NSImage
        if let mark = mark(provider.id) {
            let hex = String(format: "#%02X%02X%02X", Int(color.red * 255), Int(color.green * 255), Int(color.blue * 255))
            let svg = #"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="\#(hex)" fill-rule="\#(mark.rule.rawValue)">"#
                + mark.paths.map { #"<path d="\#($0)"/>"# }.joined() + "</svg>"
            image = NSImage(data: Data(svg.utf8)) ?? ProviderTabs.dot(color)
        } else {
            image = ProviderTabs.dot(color)
        }
        image.size = NSSize(width: size, height: size)
        image.isTemplate = false
        image.accessibilityDescription = provider.name
        cache[key] = image
        return image
    }

